 for(const v of s.convoys.filter(v=>allied.includes(v.f)&&visible.some(q=>dist(q.i,v.i)<6)))options.push({kind:'escort',target:v.i,score:2.8-dist(a.i,v.i)*.07});
 options.sort((a,b)=>(b.score-(used.has(b.target)?.9:0))-(a.score-(used.has(a.target)?.9:0))||a.target-b.target);
