export const CAMPAIGN_GOALS={independence:'Независимость',regional:'Региональное могущество',trade:'Торговая гегемония',technology:'Технологическое лидерство',maritime:'Морское господство',overseas:'Заморская экспансия',central:'Централизация',federation:'Федерация',prosperity:'Благосостояние'};
